#include <fstream>
#include <iostream>
#include <sstream>

struct Recuento {
    int aceptados;
    int rechazados;
};

bool recuento_valido(const Recuento& valor) {
    return valor.aceptados >= 0 && valor.aceptados <= 10
        && valor.rechazados >= 0 && valor.rechazados <= 10;
}

std::ostream& operator<<(std::ostream& destino, const Recuento& valor) {
    return destino << '[' << valor.aceptados << ';' << valor.rechazados << ']';
}

int main() {
    const Recuento resumen{3, 2};
    std::ostringstream captura;
    captura << resumen << ";fin";
    std::ofstream archivo{"recuento_lgp.txt"};
    if (!archivo) {
        std::cout << "Error apertura";
        return 1;
    }
    archivo << resumen;
    archivo.close();
    if (!archivo) {
        std::cout << "Error escritura";
        return 1;
    }
    std::cout << "Memoria=" << captura.str() << "|Guardado";
    return 0;
}

#include <fstream>
#include <iostream>
#include <sstream>

struct Recuento {
    int aceptados;
    int rechazados;
};

bool recuento_valido(const Recuento& valor) {
    return valor.aceptados >= 0 && valor.aceptados <= 10
        && valor.rechazados >= 0 && valor.rechazados <= 10;
}

std::ostream& operator<<(std::ostream& destino, const Recuento& valor) {
    return destino << '[' << valor.aceptados << ';' << valor.rechazados << ']';
}

int probar(const Recuento& resumen) {
    std::ostringstream captura;
    captura << resumen << ";fin";
    std::ofstream archivo{"recuento_lgp.txt"};
    if (!archivo) {
        std::cout << "Error apertura";
        return 1;
    }
    archivo << resumen;
    archivo.close();
    if (!archivo) {
        std::cout << "Error escritura";
        return 1;
    }
    std::cout << "Memoria=" << captura.str() << "|Guardado\n";
    return 0;
}

int main() {
    if (probar({3, 2}) != 0) return 1;
    if (probar({0, 0}) != 0) return 1;
    if (probar({10, 10}) != 0) return 1;
    return 0;
}

