#include <iostream>
#include <sstream>
#include <string>
#include <iomanip>

struct Recuento {
    int aceptados;
    int rechazados;
};

// Completa el operador. Conserva el cliente de main.
std::ostream& operator<<(std::ostream& destino, const Recuento& valor) {
    return destino;
}

int main() {
    int a1{0}, r1{0}, a2{0}, r2{0};
    if (!(std::cin >> a1 >> r1 >> a2 >> r2)) { return 1; }
    const Recuento primero{a1, r1};
    const Recuento segundo{a2, r2};
    std::ostringstream a;
    std::ostringstream b;
    a << std::hex << primero << '|' << segundo << '|' << 10;
    b << '|' << std::setfill('.') << std::setw(4) << primero << '|' << segundo << '|' << 10;
    std::cout << "A=" << a.str() << '\n';
    std::cout << "B=" << b.str() << '\n';
    std::cout << "Originales=" << primero.aceptados << ':' << primero.rechazados
              << '|' << segundo.aceptados << ':' << segundo.rechazados << '\n';
    return 0;
}

